  var V4_ACTIVITY_META={"7":{"time":"8 min","equipment":"Open space; 8–12 students; one coloured wristband or sticky note.","setup":"Students stand shoulder-to-shoulder in a line. Mark one student so the class can track whether matter travels.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Use a clear space; no pushing or running."},"15":{"time":"12 min","equipment":"Long slinky; masking tape; floor markers.","setup":"Put one tape flag on a middle coil. Two students hold the slinky at waist height.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Do not overstretch the slinky; keep faces away from the ends."},"22":{"time":"10 min","equipment":"Stopwatch; metronome app optional; mini-whiteboards.","setup":"Pairs count repeated taps/claps over a fixed time, then compare frequency and period.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Keep sound level comfortable; use desk taps rather than loud claps if needed."},"31":{"time":"18 min","equipment":"Projector or student devices; internet; PhET Wave on a String; worksheet.","setup":"Start with damping low and a fixed tension. Students change one variable at a time.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"No physical hazard; remind students not to change several controls at once."},"41":{"time":"10 min","equipment":"Ripple tank; wave generator; stroboscope/strobe control; ruler.","setup":"Generate steady plane waves. Adjust strobe until the wavefronts appear almost stationary.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Avoid uncomfortable flashing for anyone sensitive to flicker; use alternative still images where necessary."},"48":{"time":"20 min","equipment":"Ripple tank; straight dipper; straight barrier; lamp; paper; ruler; protractor.","setup":"Produce plane waves at an angle to a straight barrier. Trace incident and reflected directions.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Keep water away from electrical connections; wipe spills immediately."},"54":{"time":"20 min","equipment":"Ripple tank; straight dipper; submerged glass/acrylic plate; lamp; ruler; protractor.","setup":"Create a clear deep/shallow boundary. Send plane waves obliquely across it.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Handle glass plate carefully; use acrylic if available; keep electrical parts dry."},"61":{"time":"20 min","equipment":"Ripple tank; two barriers; ruler; straight dipper; optional PhET Wave Interference.","setup":"Teams compete to create the strongest and weakest diffraction while explaining how they did it.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Same ripple-tank precautions; avoid touching moving dipper."},"65":{"time":"18 min","equipment":"Paper cups; string; paper clips; ruler/tape; optional different strings.","setup":"Pairs make a cup telephone. Test one variable at a time.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Do not wrap string around fingers/neck; keep walkways clear."},"67":{"time":"8 min","equipment":"Tuning fork; rubber striker; shallow tray/beaker of water; paper towel.","setup":"Strike tuning fork gently and touch the vibrating prongs to the water surface.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Use a rubber striker; never strike on hard surfaces; wipe water spills."},"66":{"time":"15 min","equipment":"Included MythBusters Jr. clip; mini-whiteboards or paper.","setup":"Pause before the key result. Every student commits to a prediction before viewing evidence.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"No physical hazard; keep video volume comfortable."},"77":{"time":"15 min","equipment":"CRO Flash/PhET Waves Intro Sound; speaker at low volume; mini-whiteboards.","setup":"Show pairs of waveforms or tones where only one variable changes.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Keep sound volume low; do not use very loud or uncomfortable high-frequency tones."},"83":{"time":"15 min","equipment":"Included echolocation video; calculators; ruler; scenario cards.","setup":"After the video, give teams different echo times and a speed of sound. They calculate one-way distance.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"No physical hazard."},"87":{"time":"12 min","equipment":"Seven printed spectrum cards; use/source cards; open space.","setup":"Seven students hold EM region cards and must arrange themselves by increasing wavelength without notes.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Keep walkway clear."},"102":{"time":"20 min","equipment":"Ray boxes; plane mirrors; white paper; rulers; protractors; target card.","setup":"Create a target on paper. Teams use one or two mirrors to direct a ray to the target, then justify the path.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Use ray boxes, not handheld lasers; avoid looking directly into bright beams."},"110":{"time":"10 min","equipment":"Opaque cup/bowl; coin; water jug; towel.","setup":"Place coin so a seated observer just cannot see it over the rim. Without moving head/cup, add water.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Wipe spills; use plastic cup if preferred."},"112":{"time":"18 min","equipment":"Projector/student devices; internet; PhET Bending Light; worksheet.","setup":"Students compare air→water and air→glass using the on-screen protractor.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"No physical hazard."},"120":{"time":"18 min","equipment":"Semicircular acrylic block; ray box; paper; protractor.","setup":"Send light through the curved face so it reaches the flat face from inside the block.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Use ray box; avoid direct eye exposure; handle block carefully."},"134":{"time":"22 min","equipment":"Converging lens; lens holder; illuminated object/window; white screen; metre rule; optional PhET Geometric Optics.","setup":"Teams must produce three different image types/sizes by changing object distance.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Do not focus sunlight with the lens; use classroom objects/light sources only."},"138":{"time":"25 min","equipment":"Printed lock cards from Student Activities page; calculators; mini-whiteboards; optional envelopes.","setup":"Teams solve six short locks: wave type, T/f, v=fλ, diffraction, echo, optics. Teacher checks each code before next lock.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"No physical hazard; keep competition cooperative."},"19":{"time":"10 min","equipment":"Mini-whiteboards/A4 paper; coloured pens; slide 19 video.","setup":"Pause the wave-properties video and run a team label relay.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"No physical hazard."},"39":{"time":"12 min","equipment":"Slide 39 virtual ripple tank; mini-whiteboards.","setup":"Start paused; compare straight dipper, point source and frequency changes.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Virtual activity."},"40":{"time":"8 min","equipment":"Floor line/tape; arrow card; open space.","setup":"Students form a human wavefront and place the ray at 90 degrees.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Clear floor space; no running."},"46":{"time":"12 min","equipment":"Slide 46 reflection animation; mini-whiteboards; optional protractors.","setup":"Predict reflection angle before reading the animation value.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Virtual activity."},"78":{"time":"12 min","equipment":"Included slow-motion glass video; mini-whiteboards.","setup":"Prediction then evidence then explanation; video only.","answer":"Student edition: write your own prediction, evidence and physics explanation. Discuss it with your teacher before checking any class answer.","safety":"Video only; comfortable audio level."}};
