  // V18 — SOW alignment: EM spectrum is taught before Sound. Original slide numbers stay unchanged.
  function getV18Slide(n){return slides.find(function(x){return Number(x.sourceSlide)===n && !x.activitySlide;});}
  function emMiniWave(cls,cycles){var d='';for(var x=0;x<=240;x+=4){var y=44+22*Math.sin((x/240)*Math.PI*2*cycles);d+=(x===0?'M':'L')+x.toFixed(0)+' '+y.toFixed(1)+' ';}return '<svg class="em-mini-wave '+cls+'" viewBox="0 0 240 88" aria-hidden="true"><path d="'+d+'"/></svg>';}
  function emCard(cls,name,tag,visual,source,detect,use,hazard){
    var nasaVideos={
      radio:'https://www.youtube.com/watch?v=OzDmEA8x0nQ',
      micro:'https://www.youtube.com/watch?v=UZeBzTI5Omk',
      ir:'https://www.youtube.com/watch?v=i8caGm9Fmh0',
      visible:'https://www.youtube.com/watch?v=PMtC34pzKGc',
      uv:'https://www.youtube.com/watch?v=QW5zeVy8aE0',
      xray:'https://www.youtube.com/watch?v=CCAYcuCWOnM',
      gamma:'https://www.youtube.com/watch?v=TA5SLDiIUWs'
    };
    var video=nasaVideos[cls]||'https://science.nasa.gov/ems/';
    return '<article class="em-region-card '+cls+'"><div class="em-card-head"><h2>'+name+'</h2><span>'+tag+'</span></div>'+visual+'<div class="em-facts"><p><b>Source</b>'+source+'</p><p><b>Detect</b>'+detect+'</p><p><b>Use</b>'+use+'</p><p><b>Safety</b>'+hazard+'</p></div><a class="em-nasa-link" href="'+video+'" target="_blank" rel="noopener">▶ NASA VIDEO • '+name+' ↗</a></article>';
  }
  var s87=getV18Slide(87); if(s87){s87.html=heading('Lesson 13','The electromagnetic spectrum','All seven regions are the same family of transverse electromagnetic waves. What changes is wavelength, frequency and energy.','1.1t to 1.3u')+
    '<div class="em-spectrum-master"><div class="em-master-arrow"><span>LONG wavelength • LOW frequency / energy</span><b>→</b><span>SHORT wavelength • HIGH frequency / energy</span></div><div class="em-master-bands"><span>Radio</span><span>Microwave</span><span>Infrared</span><span>Visible</span><span>Ultraviolet</span><span>X-ray</span><span>Gamma</span></div><div class="em-master-wave">'+emMiniWave('radio',1)+emMiniWave('micro',2)+emMiniWave('ir',3)+emMiniWave('visible',4)+emMiniWave('uv',5)+emMiniWave('xray',7)+emMiniWave('gamma',10)+'</div></div>'+
    '<div class="em-core-rules"><div><b>ALL EM WAVES</b><span>transverse • transfer energy • travel through vacuum • 3 × 10⁸ m/s in vacuum</span></div><div><b>MEMORY</b><span>frequency ↑ → wavelength ↓ → photon energy ↑</span></div><a href="https://science.nasa.gov/learn/heat/resource/nasa-space-place-explore-the-electromagnetic-spectrum/" target="_blank" rel="noopener">🚀 NASA interactive ↗</a></div>';}
  var s91=getV18Slide(91); if(s91){s91.html=heading('Lesson 13','EM spectrum • Radio → Visible','Each card has a visual cue plus the source, detector, use and safety point MATSEC students should know.','1.2u, 1.3u')+
    '<div class="em-card-grid four">'+
    emCard('radio','Radio','longest λ',emMiniWave('radio',1)+'<div class="em-icon-scene"><span class="tower">📡</span><i class="pulse p1"></i><i class="pulse p2"></i><i class="pulse p3"></i></div>','transmitter / aerial','aerial / receiver','radio, TV & communication','non-ionising; high-power exposure can heat tissue')+
    emCard('micro','Microwaves','cm–mm',emMiniWave('micro',2)+'<div class="em-icon-scene"><span>🛰️</span><span class="beam">⇢</span><span>📱</span></div>','magnetron / transmitter','receiver / aerial','satellite, mobile, cooking','non-ionising; strong exposure heats tissue')+
    emCard('ir','Infrared','felt as heat',emMiniWave('ir',3)+'<div class="em-icon-scene heat"><span>🌡️</span><span>🔥</span><span>📷</span></div>','warm objects / IR LED','IR sensor / thermistor','remote controls & thermal imaging','strong IR can heat skin/eyes')+
    emCard('visible','Visible','we can see it',emMiniWave('visible',4)+'<div class="em-visible-strip"></div><div class="em-icon-scene"><span>☀️</span><span>👁️</span><span>📷</span></div>','Sun / lamps','eye / camera','vision, photography, fibre optics','very bright light / lasers can damage eyes')+
    '</div>';}
  var s92=getV18Slide(92); if(s92){s92.html=heading('Lesson 13','EM spectrum • UV → Gamma','These are the higher-frequency regions. UV, X-rays and gamma can damage living cells; X-rays and gamma are ionising.','1.2u, 1.3u')+
    '<div class="em-card-grid three">'+
    emCard('uv','Ultraviolet','beyond violet',emMiniWave('uv',5)+'<div class="em-icon-scene"><span>☀️</span><span>🧴</span><span class="glow">SECURITY</span></div>','Sun / UV lamp','UV sensor / fluorescent material','security marking & sterilisation','can damage skin/eyes; raises skin-cancer risk')+
    emCard('xray','X-rays','ionising',emMiniWave('xray',7)+'<div class="em-xray-scene"><span>🦴</span><span>🩻</span></div>','X-ray tube','digital detector / film','medical imaging & security scanning','ionising: damages cells/DNA; limit dose')+
    emCard('gamma','Gamma','highest energy',emMiniWave('gamma',10)+'<div class="em-icon-scene"><span>☢️</span><span>🧫</span><span>🎯</span></div>','radioactive nuclei / nuclear reactions','GM tube / radiation detector','sterilisation & radiotherapy','strongly penetrating ionising radiation')+
    '</div><div class="ionising-line"><span class="safe">mostly non-ionising</span><b>frequency / energy →</b><span class="danger">ionising risk increases at the high-energy end</span></div>';}

  // Extra SOW slides without disturbing the original 1–94 references.
  var idx92=slides.findIndex(function(x){return Number(x.sourceSlide)===92 && !x.activitySlide;});
  if(idx92>=0){slides.splice(idx92+1,0,
    {title:'EM safety • ionising vs non-ionising',sourceSlide:92,displayNo:'92A',pauseable:false,className:'',html:heading('Lesson 13','Ionising vs non-ionising radiation','Do not memorise “radiation = dangerous”. Risk depends on wave type, energy and dose.','SOW • harms & uses')+'<div class="ionising-compare"><div><h2>Non-ionising</h2><p>Radio • microwave • infrared • visible</p><p>Main high-exposure effect: heating / eye damage for intense sources.</p></div><div><h2>Higher-energy / ionising end</h2><p>Ultraviolet can damage cells; X-rays and gamma are ionising.</p><p>Use shielding, distance and limited exposure where appropriate.</p></div></div><div class="big-rule">Higher frequency → higher photon energy. Useful radiation can still require controlled exposure.</div>'},
    {title:'Microwaves • energy transfer to food',sourceSlide:92,displayNo:'92B',pauseable:false,className:'',html:heading('Lesson 13','Why can microwaves heat food?','Use this as the SOW bridge from EM waves to energy transfer.','SOW • microwave application')+'<div class="microwave-demo"><div class="mw-oven"><span>MICROWAVE</span><div class="mw-wave-lines">))) ))) )))</div><div class="mw-food">💧 💧 💧</div></div><div class="mw-explain"><h2>Think → test → explain</h2><ol><li>Microwaves transfer energy to polar molecules, especially water.</li><li>Molecular motion increases.</li><li>Internal energy and temperature rise.</li></ol><div class="error-trap"><strong>Avoid:</strong> “microwaves make molecules vibrate at one magic resonance frequency.” Heating is more complicated than that.</div></div></div>'}
  );}

  // Move the whole EM block (86–94, including activity/suffix slides) before the Sound block (64–85).
  slides=slides.filter(function(s){return Number(s.sourceSlide)<=94;});
  var emBlock=slides.filter(function(x){var n=Number(x.sourceSlide);return n>=86&&n<=94;});
